tool_use_result.originalFile:
// villa-haiku: room 12, cubiculum E-S (plan x27..34, z15..20; inner air y2..5). Bedchamber off the atrium.
// Door (26, 2..3, 17) in the west wall; window (35, 3..4, 17..18) in the east wall. Plan coordinates throughout.
// Layout: the bed lies along the north wall (headboard on the wall), a bedside lamp at its head, the lectern and its
// stool under the east window for reading light. The door-to-bed walk is the open floor along z17..18.
import { BED, COURT, COUCH, LECTERN, PILLAR, LANTERN, CUSHION } from "../vocab.mjs";

// a bed is two cells: the head against the wall, the foot toward the room. facing = foot -> head.
const bedHead = (g, x, z, facing) => g.set(x, 2, z, BED, { facing, part: "head", occupied: "false" });
const bedFoot = (g, x, z, facing) => g.set(x, 2, z, BED, { facing, part: "foot", occupied: "false" });

export function build(g) {
  // the bed: head at (33,15) against the north wall, foot at (33,16), facing north (foot -> head)
  bedHead(g, 33, 15, "north");
  bedFoot(g, 33, 16, "north");

  // the bedside lamp: a standing lamp at the head, beside the bed (the room's north-east corner)
  g.set(34, 2, 15, PILLAR, { axis: "y" });
  g.set(34, 3, 15, LANTERN, { hanging: "false", waterlogged: "false" });

  // the reading station: a lectern under the east window (book faces west, into the room), with a stool
  g.set(34, 2, 18, LECTERN, { facing: "west", has_book: "true", powered: "false" });
  g.set(33, 2, 18, COUCH, { facing: "east", half: "bottom", shape: "straight", waterlogged: "false" });

  // a red rug in front of the bed: carpets are walkable, so the path up to the bed stays clear
  g.set(32, 2, 16, CUSHION);
  return g;
}

