const [sx, sy, sz] = g.size;
for (let x = 0; x < sx; x++) for (let y = 0; y < sy; y++) for (let z = 0; z < sz; z++) {
  const cut = (x <= 26 && z >= 14 && z <= 21) || (z >= 21 && x >= 22 && x <= 35 && y >= 2) || (z <= 14 && z >= 13 && x >= 26);
  if (cut && y >= 2) g.unset(x, y, z);
}
g.save(process.argv[3]);
EOF
