cat > /tmp/ascii-room12.mjs <<'EOF'
// temp view only: the room's y2 layer as text, plan coordinates (file z = plan z + 4)
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const g = await load(process.argv[2]);
const sym = { air: ".", bed: "B", lectern: "L", lantern: "*", pillar: "|", stairs: "S", carpet: "c", mosaic: "m", door: "D", bars: "#", plaster: "w", water: "~" };
for (const y of [2, 3]) {
  console.log(`y${y}  x27..34 (plan z15..20)`);
  for (let z = 14; z <= 21; z++) {
    let row = "";
    for (let x = 26; x <= 35; x++) {
      const b = g.get(x, y, z + 4);
      const name = (b && (b.block ?? b[0] ?? b.name ?? "")) + "";
      row += name.includes("bed") ? "B" : name.includes("lectern") ? "L" : name.includes("lantern") ? "*" : name.includes("pillar") ? "|" : name.includes("stairs") ? "S" : name.includes("carpet") ? "c" : name.includes("door") ? "D" : name.includes("bars") ? "#" : name.includes("air") || !name ? "." : name.includes("terracotta") ? "t" : "w";
    }
    console.log(`z${String(z).padStart(2)} ${row}`);
  }
}
EOF
node /tmp/ascii-room12.mjs build.nbt 2>&1 | head -30; date

