input.content:
// temp view only: the room's floor and head layers as text, plan coordinates (file z = plan z + 4)
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const g = await load(process.argv[2]);
const sym = (b) => {
  if (!b) return ".";
  const name = String(Array.isArray(b) ? b[0] : (b.block ?? b.name ?? ""));
  if (name.includes("air")) return ".";
  if (name.includes("bed")) return "B";
  if (name.includes("lectern")) return "L";
  if (name.includes("lantern")) return "*";
  if (name.includes("pillar")) return "|";
  if (name.includes("stairs")) return "S";
  if (name.includes("carpet")) return "c";
  if (name.includes("door")) return "D";
  if (name.includes("bars")) return "#";
  if (name.includes("terracotta")) return "t";
  if (name.includes("pot")) return "p";
  return "w";
};
for (const y of [2, 3]) {
  console.log(`y${y}  x26..35 (plan), z14..21 (plan)`);
  for (let z = 14; z <= 21; z++) {
    let row = "";
    for (let x = 26; x <= 35; x++) row += sym(g.get(x, y, z + 4));
    console.log(`z${String(z).padStart(2)} ${row}`);
  }
}

